function processAdvisories(inputJson) {
    const result = {};

    // Validate input
    if (
        typeof inputJson !== "object" ||
        inputJson === null ||
        !Array.isArray(inputJson.recommendations)
    ) {
        return result;
    }

    for (const recommendation of inputJson.recommendations) {
        const env = recommendation.environment || {};
        const hostName = env.host_name || "unknown_host";
        const advisories = new Set(); // use Set to avoid duplicates

        const patchesBySeverity = recommendation.patches || {};

        for (const severity of ["critical", "high", "medium", "low"]) {
            const patches = patchesBySeverity[severity] || [];

            for (const patch of patches) {
                const advisory = patch?.advisory;
                const metadata = patch?.metadata || {};
                let command = "";

                if (env.version === "2023") {
                    if (
                        typeof metadata["issue_correction"] === "string" &&
                        metadata["issue_correction"].trim() !== ""
                    ) {
                        command = metadata["issue_correction"].trim() + " -y";
                    } else if (advisory) {
                        command = `dnf upgrade -y --releasever=latest --advisory=${advisory}`;
                    }
                } else if (env.version === "2" && advisory) {
                    command = `dnf update -y --advisory=${advisory}`;
                }

                if (command) {
                    advisories.add(command);
                }
            }
        }

        result[hostName] = Array.from(advisories);
    }

    return result;
}

