function getAuthByIP(ip, config_data) {
    if (typeof config_data !== "object" || config_data === null || !Array.isArray(config_data.config)) {
        return null;
    }

    for (const item of config_data.config) {
        if (item && Array.isArray(item.host) && item.host.includes(ip)) {
            return item.auth || null;
        }
    }

    return null;
};

